# shellcheck shell=bash
# strict-mode: opt-out sourced library; it must not change the caller's shell options
# Generated by OrchestKit Claude Plugin
# Created: 2026-11-20
#
# resolve_base_ref: print the ref visualize-plan measures the branch against.
# A remote-tracking ref wins over the local branch of the same name: worktrees
# rarely pull main, so a local main can lag origin by hundreds of commits and
# every count would include upstream work (#5194). Order: main, else the
# remote's default branch; dev instead when the branch was cut from dev.

# Print origin/<name>, else <name>, whichever names a commit.
_plan_base_tracking_ref() {
  local ref
  for ref in "origin/$1" "$1"; do
    if git rev-parse --verify --quiet "${ref}^{commit}" >/dev/null; then
      echo "${ref}"
      return 0
    fi
  done
  return 1
}

resolve_base_ref() {
  local base default dev main_fork dev_fork
  if ! base=$(_plan_base_tracking_ref main); then
    default=$(git symbolic-ref --quiet --short refs/remotes/origin/HEAD 2>/dev/null || true)
    base=$(_plan_base_tracking_ref "${default#origin/}" 2>/dev/null || echo main)
  fi
  if dev=$(_plan_base_tracking_ref dev); then
    main_fork=$(git merge-base HEAD "${base}" 2>/dev/null || true)
    dev_fork=$(git merge-base HEAD "${dev}" 2>/dev/null || true)
    # dev wins only when the branch left dev after it left main; a dev that
    # main has moved past would otherwise pull main's newer commits in.
    if [ -n "${dev_fork}" ] && [ "${dev_fork}" != "${main_fork}" ] &&
      { [ -z "${main_fork}" ] || git merge-base --is-ancestor "${main_fork}" "${dev_fork}"; }; then
      base="${dev}"
    fi
  fi
  echo "${base}"
}
